int16_t montgomery_reduce(int32_t a)
{
  int32_t t;
  int16_t u;

  u = a * QINV;
  t = (int32_t)u * DTRU_Q;
  t = a - t;
  t >>= 16;
  return t;
}

int16_t barrett_reduce(int16_t a)
{
  int32_t t;

  t = BARRETT_V * a;
  t >>= 26;
  t *= DTRU_Q;
  return a - t;
}

int16_t fqcsubq(int16_t a)
{
  a += (a >> 15) & DTRU_Q;
  a -= DTRU_Q;
  a += (a >> 15) & DTRU_Q;
  return a;
}

int16_t fqinv(int16_t a)
{
  int16_t exp, t = 1;

  a = fqmul(a, 867); // aR = fqmul(a, R^2), (R^2 = 2^32 = 867 mod q)
  for (exp = DTRU_Q - 2; exp > 0; exp >>= 1)
  {
    if (exp & 1)
      t = fqmul(t, a);
    a = fqmul(a, a);
  }
  return t;
}

int16_t fqmul(int16_t a, int16_t b)
{
  return montgomery_reduce((int32_t)a * b);
}

// AVX2 optimized functions
__m256i fqcsubq_avx2(__m256i a, __m256i q_vec)
{
    __m256i mask;

    // mask = (a < 0) ? 0xFFFF : 0x0000
    mask = _mm256_srai_epi16(a, 15);
    a = _mm256_add_epi16(a, _mm256_and_si256(mask, q_vec));

    a = _mm256_sub_epi16(a, q_vec);

    mask = _mm256_srai_epi16(a, 15);
    a = _mm256_add_epi16(a, _mm256_and_si256(mask, q_vec));

    return a;
}

__m256i _mm256_barrett_epi16(__m256i h, __m256i barrett_v_vec, __m256i qvec)
{
    __m256i t = _mm256_mulhi_epi16(h, barrett_v_vec);
    t = _mm256_srai_epi16(t, 10);
    t = _mm256_mullo_epi16(t, qvec);
    return _mm256_sub_epi16(h, t);
}

__m256i _mm256_fqmul_epi16(__m256i h1, __m256i h2, __m256i qvec, __m256i qinvvec)
{
    __m256i h = _mm256_mulhi_epi16(h1, h2); // a_high
    h1 = _mm256_mullo_epi16(h1, h2);        // a_low
    h1 = _mm256_mullo_epi16(h1, qinvvec);   // (a * qinv)_low
    h2 = _mm256_mulhi_epi16(h1, qvec);
    return _mm256_sub_epi16(h, h2);         // mont_redc(h1 * h2)
}

__m256i _mm256_fqinv_epi16(__m256i a, __m256i qvec, __m256i qinvvec)
{
    __m256i t = a;
    for (int i = 1; i < 7; i++) {
        a = _mm256_fqmul_epi16(a, a, qvec, qinvvec);
        t = _mm256_fqmul_epi16(a, t, qvec, qinvvec);
    }

    // i = 7
    a = _mm256_fqmul_epi16(a, a,qvec, qinvvec);

    // i = 8
    a = _mm256_fqmul_epi16(a, a, qvec, qinvvec);
    t = _mm256_fqmul_epi16(a, t, qvec, qinvvec);

    // i = 9
    a = _mm256_fqmul_epi16(a, a, qvec, qinvvec);

    // i = 10
    a = _mm256_fqmul_epi16(a, a, qvec, qinvvec);
    t = _mm256_fqmul_epi16(a, t, qvec, qinvvec);

    // i = 11
    a = _mm256_fqmul_epi16(a, a, qvec, qinvvec);
    t = _mm256_fqmul_epi16(a, t, qvec, qinvvec);

    return t;
}